questionText:
Voici un extrait de code. Quelle ligne permet d'envoyer une réponse au client qui a émis l'événement ?

<pre style='background:#2d2d2d; color:#f8f8f2; padding:8px; border-radius:4px;'>
@SubscribeMessage('message')
handleMessage(client: Socket, payload: any) {
  // Ligne A
  client.emit('response', { status: 'ok' });

  // Ligne B
  this.server.emit('response', { status: 'ok' });

  // Ligne C
  client.to(client.id).emit('response', { status: 'ok' });

  // Ligne D
  this.server.to('room').emit('response', { status: 'ok' });
}
</pre>
